import React, { useRef } from 'react';
import { numberFieldDependencies } from './neon-number-field';
import { selectFieldDependencies } from './neon-select-field';
import { buttonDependencies } from './neon-button';
import { buildPropsMap, createComponentDependency, 
//useImperativeProps,
useListeners, withNeonWebComponent, toAttribute } from './utils/react-utils';
export const paginationDependencies = [
    createComponentDependency('pagination'),
    ...numberFieldDependencies,
    ...selectFieldDependencies,
    ...buttonDependencies
];
function Pagination(props) {
    const elementRef = useRef();
    // * * * Set Props * * *
    // useImperativeProps<NeonPaginationElement>(elementRef, {
    //   //propName: propValue
    // });
    // * * * Set Listeners * * *
    useListeners(elementRef, {
        neonPaginationPageLengthChange: (e) => {
            if (props.neonPaginationPageLengthChange != null) {
                props.neonPaginationPageLengthChange(e.detail.pageLength, e.detail.getPaginatedData);
            }
        },
        neonPaginationPageChange: (event) => {
            if (props.neonPaginationPageChange != null) {
                props.neonPaginationPageChange(event.detail.page, event.detail.getPaginatedData);
            }
        },
        neonPaginationChange: (event) => {
            if (props.neonPaginationChange != null) {
                props.neonPaginationChange(event.detail.page, event.detail.pageLength, event.detail.getPaginatedData);
            }
        }
    });
    // * * * Set Attributes * * *
    return React.createElement('neon-2_20_1-pagination', buildPropsMap(props, {
        ref: elementRef,
        'data-use-component-spacing': toAttribute(props.dataUseComponentSpacing),
        'data-current-page': props.dataCurrentPage,
        'data-array-length': props.dataArrayLength,
        'data-page-length': props.dataPageLength,
        'data-show-results': toAttribute(props.dataShowResults),
        'data-show-jump-to': toAttribute(props.dataShowJumpTo),
        'data-show-page-numbers': toAttribute(props.dataShowPageNumbers),
        'data-show-page-size-select': toAttribute(props.dataShowPageSizeSelect),
        'data-page-size-options': props.dataPageSizeOptions,
        'data-show-single-page': toAttribute(props.dataShowSinglePage)
    })
    //props.children can be passed in as the next argument into React.createElement() if the element is expected to have children.
    );
}
export const NeonPagination = withNeonWebComponent('neon-2_20_1-pagination', Pagination, paginationDependencies);
